/* Bank soal latihan per bagian TKA Bahasa Indonesia SD (teks & soal orisinal).
   Setiap soal: lv (1 mudah, 2 sedang, 3 sulit), sub, t (pg/pgk/bs), q, o, ans, logika, langkah, cepat, simpel.
   Menambah soal: tambahkan di PALING BAWAH daftar soal topiknya agar soal yang disimpan tidak bergeser. */
var NS='bi-';var MAPEL='Bahasa Indonesia';
const F=(a,b)=>`<span class="fr"><span>${a}</span><span>${b}</span></span>`;
const TX=h=>`<div class="teks">${h}</div>`;

const ELEMEN=[
 {id:'info',nama:'Teks Informasi',c:'#d9480f',cl:'#fff0e6',ic:'📰'},
 {id:'sastra',nama:'Teks Sastra',c:'#c2255c',cl:'#fff0f3',ic:'📖'},
 {id:'bahasa',nama:'Kebahasaan & Penalaran',c:'#2b8a3e',cl:'#ebfbee',ic:'🧩'}
];

const TOPIK=[
/* ============ 1. KOSAKATA ============ */
{id:'kosakata',el:'bahasa',ic:'🔤',nama:'Kosakata & Makna Kata',
subs:[['umumkhusus','Kosakata Umum & Khusus'],['makna','Sinonim, Antonim & Makna Kata'],['ungkapan','Ungkapan & Kiasan'],['hubung','Kata Hubung']],
konsep:`<ul><li><b>Kosakata umum</b>: cakupannya luas (bunga, hewan, kendaraan). <b>Kosakata khusus</b>: lebih rinci/menunjuk hal tertentu (mawar, kucing, sepeda motor, nama tempat).</li><li><b>Sinonim</b> = persamaan makna · <b>Antonim</b> = lawan makna. Tentukan makna kata dari <b>konteks kalimat</b>.</li><li><b>Ungkapan</b> (idiom) maknanya bukan arti kata per kata: <i>ringan tangan</i> = suka menolong, <i>besar kepala</i> = sombong.</li><li><b>Kata hubung</b>: <i>karena</i> (sebab) · <i>sehingga</i> (akibat) · <i>tetapi/sedangkan</i> (pertentangan) · <i>lalu/kemudian</i> (urutan) · <i>dan</i> (penambahan).</li></ul>`,
soal:[
{lv:1,sub:'umumkhusus',t:'pg',q:`${TX('<p>Ibu membeli <b>sayuran</b> di pasar, yaitu bayam, wortel, dan kangkung.</p>')}<p>Kata yang termasuk kosakata <b>umum</b> pada kalimat tersebut adalah …</p>`,
o:['sayuran','bayam','wortel','kangkung'],ans:0,
logika:`Kosakata umum mencakup banyak anggota, sedangkan kosakata khusus adalah salah satu anggotanya.`,
langkah:`Bayam, wortel, dan kangkung adalah <b>jenis-jenis</b> sayuran. Jadi "sayuran" adalah kata yang mencakup ketiganya, sehingga termasuk kosakata umum.`,
cepat:`Tanya: "Kata mana yang bisa jadi 'payung' untuk kata lain?" Payungnya = kosakata umum.`,
simpel:`Bayam, wortel, dan kangkung semuanya termasuk sayuran. Jadi "sayuran" adalah kata umumnya.`},
{lv:1,sub:'makna',t:'pg',q:`${TX('<p>Adik sangat <b>gembira</b> ketika Ayah pulang membawa mainan baru.</p>')}<p>Sinonim kata yang dicetak tebal adalah …</p>`,
o:['senang','sedih','takut','heran'],ans:0,
logika:`Sinonim adalah kata yang maknanya sama atau mirip.`,
langkah:`Gembira = senang. Sedih adalah antonimnya. Takut dan heran memiliki makna lain.`,
cepat:`Ganti kata tebal dengan pilihan jawaban. Kalau makna kalimatnya tetap sama, itulah sinonimnya.`,
simpel:`Gembira artinya senang.`},
{lv:1,sub:'hubung',t:'pg',q:`${TX('<p>Rudi terlambat masuk sekolah <b>…</b> bangun kesiangan.</p>')}<p>Kata hubung yang tepat untuk mengisi titik-titik adalah …</p>`,
o:['karena','sehingga','tetapi','dan'],ans:0,
logika:`Bagian setelah titik-titik ("bangun kesiangan") adalah <b>sebab</b> dari terlambat.`,
langkah:`Kata hubung untuk menyatakan sebab adalah "karena". "Sehingga" dipakai untuk akibat, "tetapi" untuk pertentangan, dan "dan" untuk penambahan.`,
cepat:`Tanyakan "mengapa?" Mengapa terlambat? Karena bangun kesiangan.`,
simpel:`Bangun kesiangan itu alasan Rudi terlambat. Kata untuk alasan adalah "karena".`},
{lv:2,sub:'umumkhusus',t:'bs',label:['Khusus','Umum'],q:`${TX('<p>Pada liburan sekolah, keluarga Dita pergi ke <b>Danau Toba</b> dengan <b>kendaraan</b> pribadi. Di sana mereka membeli <b>oleh-oleh</b> berupa <b>bika ambon</b>.</p>')}<p>Tentukan apakah kata berikut termasuk kosakata khusus atau umum!</p>`,
o:['Danau Toba','kendaraan','bika ambon'],ans:[true,false,true],
logika:`Nama tempat dan nama benda tertentu termasuk kosakata khusus. Kata yang mencakup banyak jenis termasuk kosakata umum.`,
langkah:`Danau Toba = nama danau tertentu → khusus.<br>Kendaraan bisa mobil, motor, atau bus → umum.<br>Bika ambon = jenis kue tertentu → khusus.`,
cepat:`Kalau kata itu bisa dijawab dengan "yang mana?", berarti kata umum. Contohnya: "Kendaraan yang mana?"`,
simpel:`Danau Toba dan bika ambon menunjuk benda tertentu, jadi khusus. Kendaraan masih umum karena bisa mobil, motor, atau bus.`},
{lv:2,sub:'ungkapan',t:'pg',q:`${TX('<p>Pak Hasan dikenal <b>ringan tangan</b> oleh warga kampung. Ia selalu datang paling awal saat ada tetangga yang membutuhkan bantuan.</p>')}<p>Makna ungkapan <b>ringan tangan</b> pada teks tersebut adalah …</p>`,
o:['suka menolong','suka memukul','tangannya kecil','malas bekerja'],ans:0,
logika:`Ungkapan bisa punya dua makna. Lihat kalimat sesudahnya untuk menentukan makna yang dimaksud.`,
langkah:`Kalimat kedua menjelaskan Pak Hasan "selalu datang … saat tetangga membutuhkan bantuan". Jadi ringan tangan di sini bermakna <b>suka menolong</b>.`,
cepat:`Konteks kalimat adalah kunci. Ungkapan yang sama bisa bermakna lain kalau kalimatnya berbeda.`,
simpel:`Pak Hasan selalu membantu tetangga, jadi ringan tangan di sini artinya suka menolong.`},
{lv:2,sub:'makna',t:'pg',q:`${TX('<p>Kakak <b>menyisihkan</b> sebagian uang sakunya setiap hari untuk ditabung.</p>')}<p>Makna kata <b>menyisihkan</b> dalam kalimat tersebut adalah …</p>`,
o:['menyimpan sebagian untuk keperluan lain','membuang ke tepi jalan','menghabiskan semuanya','meminjam kepada teman'],ans:0,
logika:`Kata "menyisihkan" bisa berarti meminggirkan, tetapi dalam kalimat ini konteksnya uang yang ditabung.`,
langkah:`"Menyisihkan sebagian uang … untuk ditabung" berarti memisahkan sebagian untuk disimpan.`,
cepat:`Baca seluruh kalimat. Kata "untuk ditabung" menunjukkan maknanya adalah menyimpan.`,
simpel:`Kakak memisahkan sebagian uangnya untuk ditabung. Jadi menyisihkan artinya menyimpan sebagian.`},
{lv:3,sub:'hubung',t:'bs',q:`${TX('<p>(1) Hujan turun sangat deras <b>sehingga</b> jalan di depan sekolah tergenang.<br>(2) Andi suka bermain bola, <b>sedangkan</b> adiknya suka melukis.<br>(3) Kami mencuci tangan, <b>kemudian</b> makan siang bersama.</p>')}<p>Tentukan benar atau salah pernyataan tentang kata hubung di atas!</p>`,
o:['Kata "sehingga" pada kalimat (1) menyatakan akibat.','Kata "sedangkan" pada kalimat (2) menyatakan sebab.','Kata "kemudian" pada kalimat (3) menyatakan urutan waktu.'],ans:[true,false,true],
logika:`Tentukan hubungan makna antara bagian sebelum dan sesudah kata hubung.`,
langkah:`(1) Hujan deras → <b>akibatnya</b> jalan tergenang ✅<br>(2) Kesukaan Andi dan adiknya <b>dipertentangkan</b>, bukan sebab ❌<br>(3) Mencuci tangan dulu, <b>lalu</b> makan → urutan ✅`,
cepat:`Hafalkan 4 kelompok: sebab (karena), akibat (sehingga, maka), pertentangan (tetapi, sedangkan, namun), urutan (lalu, kemudian, setelah itu).`,
simpel:`"Sehingga" untuk akibat, "sedangkan" untuk membandingkan hal yang berbeda, dan "kemudian" untuk urutan.`},
{lv:3,sub:'ungkapan',t:'pgk',q:`${TX('<p>Setelah menang lomba, Dika menjadi <b>besar kepala</b>. Ia sering meremehkan teman-temannya. Untunglah sahabatnya, Raka, berani menasihatinya. Raka memang <b>berhati emas</b>, selalu tulus membantu siapa saja.</p>')}<p>Pernyataan yang tepat tentang makna ungkapan dalam teks adalah …</p>`,
o:['"Besar kepala" bermakna sombong.','"Berhati emas" bermakna baik hati.','"Besar kepala" bermakna pintar dan cerdas.'],ans:[0,1],
logika:`Cari petunjuk di kalimat sekitarnya. "Sering meremehkan teman" menjelaskan besar kepala. "Tulus membantu" menjelaskan berhati emas.`,
langkah:`Besar kepala → sombong (karena meremehkan teman) ✅<br>Berhati emas → baik hati (karena tulus membantu) ✅<br>Besar kepala bukan berarti pintar ❌`,
cepat:`Ungkapan selalu dijelaskan oleh kalimat di dekatnya. Garis bawahi kalimat penjelasnya.`,
simpel:`Dika jadi sombong (besar kepala). Raka baik hati (berhati emas).`},
{lv:3,sub:'makna',t:'pg',q:`${TX('<p>(1) Kucing itu <b>bisa</b> memanjat pohon dengan cepat.<br>(2) <b>Bisa</b> ular kobra sangat berbahaya.</p>')}<p>Pernyataan yang tepat tentang kata <b>bisa</b> pada kedua kalimat tersebut adalah …</p>`,
o:['Kalimat (1) bermakna mampu, kalimat (2) bermakna racun.','Keduanya bermakna mampu.','Keduanya bermakna racun.','Kalimat (1) bermakna racun, kalimat (2) bermakna mampu.'],ans:0,
logika:`Kata yang tulisannya sama bisa punya makna berbeda (homonim). Maknanya ditentukan konteks kalimat.`,
langkah:`(1) Kucing <b>mampu</b> memanjat.<br>(2) <b>Racun</b> ular kobra berbahaya.`,
cepat:`Ganti kata "bisa" dengan "mampu" atau "racun", lalu lihat mana yang masuk akal di tiap kalimat.`,
simpel:`Kucing "bisa" memanjat artinya mampu. "Bisa" ular artinya racun.`}
]},
/* ============ 2. IDE POKOK ============ */
{id:'idepokok',el:'info',ic:'💡',nama:'Ide Pokok & Gagasan Pendukung',
subs:[['idepokok','Ide Pokok Paragraf'],['pendukung','Gagasan Pendukung'],['judul','Judul & Simpulan']],
konsep:`<ul><li><b>Ide pokok</b> = inti paragraf. Biasanya ada di <b>kalimat utama</b>, yaitu kalimat pertama (deduktif) atau terakhir (induktif).</li><li><b>Gagasan pendukung</b> = kalimat penjelas berupa contoh, alasan, data, atau rincian.</li><li>Ciri kalimat utama: kalimat lain di paragraf itu <b>menjelaskan</b> kalimat tersebut.</li><li><b>Judul</b> yang tepat mewakili isi seluruh teks, tidak terlalu sempit dan tidak terlalu luas.</li></ul>`,
soal:[
{lv:1,sub:'idepokok',t:'pg',q:`${TX('<p>Kucing adalah hewan peliharaan yang mudah dirawat. Kucing dapat membersihkan tubuhnya sendiri dengan menjilati bulunya. Makanannya pun mudah didapat di toko hewan. Selain itu, kucing tidak perlu diajak berjalan-jalan setiap hari.</p>')}<p>Ide pokok paragraf tersebut adalah …</p>`,
o:['Kucing hewan peliharaan yang mudah dirawat.','Kucing menjilati bulunya.','Makanan kucing dijual di toko hewan.','Kucing tidak suka berjalan-jalan.'],ans:0,
logika:`Cari kalimat yang dijelaskan oleh kalimat-kalimat lain.`,
langkah:`Kalimat 2, 3, dan 4 adalah alasan kucing mudah dirawat. Jadi kalimat 1 adalah kalimat utama dan berisi ide pokok.`,
cepat:`Paragraf deduktif: ide pokok ada di kalimat pertama. Cek dulu kalimat pertama!`,
simpel:`Semua kalimat menjelaskan mengapa kucing mudah dirawat. Itulah ide pokoknya.`},
{lv:1,sub:'pendukung',t:'pg',q:`${TX('<p>Olahraga pagi bermanfaat bagi tubuh. Udara pagi masih segar. Tubuh yang bergerak membuat peredaran darah lancar. Olahraga pagi juga membuat kita lebih semangat belajar.</p>')}<p>Kalimat yang merupakan gagasan pendukung adalah …</p>`,
o:['Udara pagi masih segar.','Olahraga pagi bermanfaat bagi tubuh.','Olahraga harus dilakukan malam hari.','Semua orang wajib berlari setiap hari.'],ans:0,
logika:`Gagasan pendukung menjelaskan ide pokok dan terdapat di dalam paragraf.`,
langkah:`Ide pokok: olahraga pagi bermanfaat (kalimat 1). "Udara pagi masih segar" adalah salah satu penjelasnya. Pilihan lain bukan penjelas atau tidak ada di teks.`,
cepat:`Pilihan yang tidak ada di teks pasti salah. Dari yang ada di teks, pilih yang bukan kalimat utama.`,
simpel:`"Udara pagi masih segar" adalah salah satu alasan olahraga pagi bermanfaat. Jadi kalimat itu pendukung.`},
{lv:1,sub:'judul',t:'pg',q:`${TX('<p>Lebah membuat sarang dari lilin yang dihasilkan tubuhnya. Sarang itu berbentuk segi enam yang tersusun rapi. Di dalam sarang, lebah menyimpan madu dan merawat telur-telurnya.</p>')}<p>Judul yang tepat untuk paragraf tersebut adalah …</p>`,
o:['Sarang Lebah','Madu yang Manis','Hewan Bersayap','Telur Burung'],ans:0,
logika:`Judul harus mewakili seluruh isi, tidak terlalu sempit dan tidak terlalu luas.`,
langkah:`Semua kalimat membahas sarang lebah (bahan, bentuk, kegunaan). "Madu" terlalu sempit, "Hewan Bersayap" terlalu luas, dan "Telur Burung" tidak sesuai.`,
cepat:`Cari kata yang paling sering muncul dan dibahas. Di sini kata "sarang".`,
simpel:`Semua kalimatnya membahas sarang lebah. Jadi judulnya "Sarang Lebah".`},
{lv:2,sub:'idepokok',t:'pg',q:`${TX('<p>Di sekolah kami, siswa membawa botol minum sendiri. Kantin tidak lagi memakai sedotan plastik. Setiap kelas memiliki tempat sampah terpisah untuk sampah organik dan anorganik. Kebun sekolah juga diberi pupuk dari sisa makanan. Sekolah kami benar-benar menerapkan kebiasaan ramah lingkungan.</p>')}<p>Ide pokok paragraf tersebut terdapat pada kalimat …</p>`,
o:['terakhir, karena kalimat lain merupakan contoh kebiasaan ramah lingkungan','pertama, karena letaknya di awal paragraf','kedua, karena membahas kantin','keempat, karena membahas kebun sekolah'],ans:0,
logika:`Tidak semua ide pokok ada di awal. Kalau kalimat terakhir merangkum kalimat-kalimat sebelumnya, paragrafnya induktif.`,
langkah:`Kalimat 1–4 adalah contoh: botol minum, tanpa sedotan, tempat sampah terpisah, pupuk sisa makanan. Kalimat terakhir merangkum semuanya: "menerapkan kebiasaan ramah lingkungan".`,
cepat:`Kalau kalimat pertama hanya berupa contoh, langsung cek kalimat terakhir.`,
simpel:`Kalimat-kalimat awal adalah contoh, lalu kalimat terakhir menyimpulkannya. Ide pokoknya ada di akhir.`},
{lv:2,sub:'pendukung',t:'bs',q:`${TX('<p>Sungai Ciliwung kini makin tercemar. Warga sering membuang sampah rumah tangga ke sungai. Beberapa pabrik juga mengalirkan limbah tanpa diolah. Akibatnya, ikan-ikan banyak yang mati dan air berbau tidak sedap.</p>')}<p>Tentukan benar atau salah pernyataan berikut!</p>`,
o:['Ide pokok paragraf adalah Sungai Ciliwung makin tercemar.','Pembuangan limbah pabrik merupakan gagasan pendukung berupa penyebab pencemaran.','Ikan-ikan yang mati merupakan ide pokok paragraf.'],ans:[true,true,false],
logika:`Gagasan pendukung bisa berupa penyebab dan akibat dari ide pokok.`,
langkah:`Kalimat 1 = ide pokok ✅. Kalimat 2–3 = penyebab (pendukung) ✅. Kalimat 4 = akibat, juga pendukung, bukan ide pokok ❌`,
cepat:`Ide pokok hanya satu per paragraf. Sisanya pasti gagasan pendukung.`,
simpel:`Inti paragrafnya sungai tercemar. Sampah, limbah, dan ikan mati adalah penjelasannya.`},
{lv:2,sub:'judul',t:'pg',q:`${TX('<p>Gempa bumi dapat terjadi kapan saja. Saat gempa, segera berlindung di bawah meja yang kuat. Lindungi kepala dengan tangan atau tas. Jauhi jendela dan lemari yang bisa roboh. Setelah guncangan berhenti, keluar dengan tertib menuju lapangan terbuka.</p>')}<p>Judul yang paling tepat untuk teks tersebut adalah …</p>`,
o:['Cara Menyelamatkan Diri saat Gempa','Penyebab Terjadinya Gempa','Lapangan Terbuka di Sekolah','Meja yang Kuat'],ans:0,
logika:`Perhatikan isi teks: penyebab, akibat, atau langkah-langkah?`,
langkah:`Isi teks berupa langkah: berlindung, lindungi kepala, jauhi jendela, keluar dengan tertib. Jadi judulnya tentang cara menyelamatkan diri. Teks tidak membahas penyebab gempa.`,
cepat:`Teks yang berisi kata perintah (segera, lindungi, jauhi) biasanya bertema "cara …".`,
simpel:`Teksnya berisi langkah-langkah melindungi diri saat gempa. Jadi judulnya "Cara Menyelamatkan Diri saat Gempa".`},
{lv:3,sub:'pendukung',t:'pg',q:`${TX('<p>Membaca buku setiap hari memberi banyak manfaat bagi anak. Sebuah survei di sekolah kami menunjukkan bahwa 8 dari 10 siswa yang rajin membaca mendapat nilai bahasa di atas rata-rata. Membaca juga menambah kosakata dan melatih daya bayang.</p>')}<p>Kalimat pendukung yang berupa <b>data</b> untuk memperkuat ide pokok adalah …</p>`,
o:['8 dari 10 siswa yang rajin membaca mendapat nilai bahasa di atas rata-rata.','Membaca juga menambah kosakata.','Membaca melatih daya bayang.','Membaca buku setiap hari memberi banyak manfaat.'],ans:0,
logika:`Data biasanya berupa angka, hasil survei, atau hasil penelitian.`,
langkah:`Hanya kalimat kedua yang memuat angka hasil survei ("8 dari 10"). Kalimat lain adalah penjelasan biasa atau ide pokok.`,
cepat:`Soal yang meminta "data" → cari kalimat yang berisi angka atau persen.`,
simpel:`Data biasanya berupa angka. Kalimat "8 dari 10 siswa" adalah datanya.`},
{lv:3,sub:'idepokok',t:'pgk',q:`${TX('<p>(Paragraf 1) Tanaman lidah buaya mudah ditanam di pot. Tanaman ini tahan panas dan tidak perlu sering disiram.<br>(Paragraf 2) Lidah buaya juga banyak manfaatnya. Daging daunnya dapat dipakai untuk menyuburkan rambut dan meredakan kulit yang terbakar matahari.</p>')}<p>Pernyataan yang tepat tentang teks tersebut adalah …</p>`,
o:['Ide pokok paragraf 1 adalah lidah buaya mudah ditanam.','Ide pokok paragraf 2 adalah manfaat lidah buaya.','Gagasan utama seluruh teks adalah cara menyiram lidah buaya.'],ans:[0,1],
logika:`Setiap paragraf punya ide pokok sendiri. Gagasan utama seluruh teks menggabungkan ide-ide pokok itu.`,
langkah:`P1 → mudah ditanam ✅ · P2 → manfaat ✅<br>Gagasan seluruh teks: lidah buaya mudah ditanam dan bermanfaat. Menyiram hanya disebut sekilas ❌`,
cepat:`Gagasan utama seluruh teks = gabungan ide pokok setiap paragraf.`,
simpel:`Paragraf 1 membahas mudahnya menanam, paragraf 2 membahas manfaatnya. Teks tidak membahas cara menyiram.`},
{lv:3,sub:'judul',t:'bs',label:['Sesuai','Tidak Sesuai'],q:`${TX('<p>Rumah adat Toraja disebut Tongkonan. Atapnya melengkung seperti perahu. Dinding rumah dihiasi ukiran berwarna merah, hitam, dan kuning. Di depan rumah sering dipasang tanduk kerbau. Semakin banyak tanduknya, semakin tinggi kedudukan pemilik rumah.</p>')}<p>Tentukan apakah simpulan berikut sesuai atau tidak sesuai dengan teks!</p>`,
o:['Tongkonan memiliki bentuk dan hiasan yang khas.','Tanduk kerbau menunjukkan kedudukan pemilik rumah.','Semua rumah adat di Indonesia beratap seperti perahu.'],ans:[true,true,false],
logika:`Simpulan harus berdasarkan isi teks dan tidak boleh lebih luas dari yang dibahas.`,
langkah:`Atap seperti perahu, ukiran, dan tanduk = bentuk dan hiasan khas ✅ · Tanduk dan kedudukan pemilik tertulis di teks ✅<br>Teks hanya membahas Tongkonan, bukan semua rumah adat ❌`,
cepat:`Hati-hati dengan kata "semua", "selalu", dan "pasti". Simpulan seperti itu sering terlalu luas.`,
simpel:`Teksnya hanya tentang rumah Toraja. Jadi tidak bisa disimpulkan untuk semua rumah adat.`}
]},
/* ============ 3. INFORMASI TERSURAT ============ */
{id:'tersurat',el:'info',ic:'🔎',nama:'Informasi Tersurat (Teks Informasi)',
subs:[['deskripsi','Teks Deskripsi'],['prosedur','Teks Prosedur'],['laporan','Laporan & Tabel'],['berita','Berita & Pengumuman']],
konsep:`<ul><li><b>Informasi tersurat</b> = tertulis langsung di teks. Jawabannya bisa ditunjuk kalimatnya.</li><li>Strategi: baca pertanyaan dulu → cari <b>kata kunci</b> → temukan kalimat di teks → cocokkan.</li><li><b>Teks prosedur</b>: perhatikan urutan langkah dan kata seperti "setelah", "sebelum", "terakhir".</li><li><b>Berita</b>: unsur 5W+1H (apa, siapa, kapan, di mana, mengapa, bagaimana).</li><li>Pilihan yang menambah informasi yang <b>tidak ada</b> di teks pasti salah.</li></ul>`,
soal:[
{lv:1,sub:'deskripsi',t:'pg',q:`${TX('<p>Pasar apung di Banjarmasin berada di atas sungai. Para pedagang berjualan di atas perahu kayu yang disebut jukung. Mereka menjual sayur, buah, dan kue tradisional. Pasar ini ramai sejak subuh hingga pukul sembilan pagi.</p>')}<p>Para pedagang di pasar apung berjualan di atas …</p>`,
o:['perahu kayu yang disebut jukung','meja di tepi sungai','kios di dalam gedung','gerobak dorong'],ans:0,
logika:`Cari kata kunci "berjualan di atas" di dalam teks.`,
langkah:`Kalimat kedua: "Para pedagang berjualan di atas perahu kayu yang disebut jukung."`,
cepat:`Soal tersurat: jawabannya ada kata per kata di teks. Langsung cari kalimatnya.`,
simpel:`Di teks tertulis pedagang berjualan di atas perahu bernama jukung.`},
{lv:1,sub:'prosedur',t:'pg',q:`${TX('<p><b>Cara Mencuci Tangan</b><br>1. Basahi tangan dengan air mengalir.<br>2. Tuangkan sabun secukupnya.<br>3. Gosok telapak, punggung tangan, dan sela-sela jari selama 20 detik.<br>4. Bilas dengan air mengalir.<br>5. Keringkan dengan handuk bersih atau tisu.</p>')}<p>Langkah yang dilakukan setelah menuangkan sabun adalah …</p>`,
o:['menggosok telapak, punggung tangan, dan sela-sela jari','membasahi tangan dengan air','mengeringkan tangan dengan tisu','membilas dengan air mengalir'],ans:0,
logika:`"Setelah menuangkan sabun" berarti langkah sesudah langkah 2.`,
langkah:`Menuangkan sabun = langkah 2 → langkah berikutnya, langkah 3, adalah menggosok tangan.`,
cepat:`Temukan nomor langkah yang disebut di soal, lalu lihat nomor sesudah atau sebelumnya.`,
simpel:`Setelah memakai sabun, tangan digosok (langkah 3).`},
{lv:1,sub:'berita',t:'pg',q:`${TX('<p><b>PENGUMUMAN</b><br>Diberitahukan kepada seluruh siswa kelas 4–6 bahwa latihan pramuka hari Jumat, 7 Juni, <b>diundur</b> menjadi hari Sabtu, 8 Juni, pukul 07.30 di lapangan sekolah karena lapangan dipakai untuk upacara peringatan hari jadi kota.</p>')}<p>Mengapa latihan pramuka diundur?</p>`,
o:['Lapangan dipakai untuk upacara peringatan hari jadi kota.','Pembina pramuka sedang sakit.','Hari Jumat turun hujan deras.','Siswa kelas 4–6 sedang ujian.'],ans:0,
logika:`Pertanyaan "mengapa" mencari alasan. Cari kata "karena" di teks.`,
langkah:`"… karena lapangan dipakai untuk upacara peringatan hari jadi kota."`,
cepat:`Pertanyaan "mengapa" → cari kata karena, sebab, atau oleh karena itu.`,
simpel:`Di pengumuman tertulis alasannya: lapangan dipakai untuk upacara.`},
{lv:2,sub:'laporan',t:'bs',q:`${TX('<p><b>Hasil Pengamatan Pertumbuhan Kacang Hijau</b></p><table style="border-collapse:collapse;font-size:14px;width:100%"><tr><th style="border:1px solid #ddd">Hari ke-</th><th style="border:1px solid #ddd">Tanaman A (disiram)</th><th style="border:1px solid #ddd">Tanaman B (tidak disiram)</th></tr><tr><td style="border:1px solid #ddd">2</td><td style="border:1px solid #ddd">Muncul akar</td><td style="border:1px solid #ddd">Tidak berubah</td></tr><tr><td style="border:1px solid #ddd">4</td><td style="border:1px solid #ddd">Tinggi 3 cm</td><td style="border:1px solid #ddd">Biji mengering</td></tr><tr><td style="border:1px solid #ddd">6</td><td style="border:1px solid #ddd">Tinggi 7 cm, daun 2 helai</td><td style="border:1px solid #ddd">Tidak tumbuh</td></tr></table>')}<p>Tentukan benar atau salah pernyataan berdasarkan tabel!</p>`,
o:['Tanaman A sudah muncul akar pada hari ke-2.','Pada hari ke-6, tinggi tanaman A 7 cm.','Tanaman B tumbuh setinggi 3 cm pada hari ke-4.'],ans:[true,true,false],
logika:`Baca tabel per baris (hari) dan per kolom (tanaman). Jangan tertukar kolomnya.`,
langkah:`Hari 2, tanaman A: muncul akar ✅ · Hari 6, tanaman A: 7 cm ✅<br>Hari 4, tanaman B: biji mengering (yang 3 cm adalah tanaman A) ❌`,
cepat:`Tunjuk dengan jari: baris hari → kolom tanaman → baca isinya.`,
simpel:`Tanaman A yang disiram tumbuh. Tanaman B tidak tumbuh, jadi pernyataan 3 salah.`},
{lv:2,sub:'berita',t:'pgk',q:`${TX('<p>SURABAYA – Sebanyak 500 pelajar mengikuti kegiatan menanam bakau di Pantai Kenjeran pada Minggu (5/1). Kegiatan yang diadakan Dinas Lingkungan Hidup itu bertujuan mencegah abrasi atau pengikisan pantai oleh ombak. Setiap pelajar menanam dua bibit bakau. "Bakau ini akan melindungi pantai dan menjadi rumah bagi ikan kecil," ujar Ibu Ratna, salah satu panitia.</p>')}<p>Informasi yang sesuai dengan isi berita adalah …</p>`,
o:['Kegiatan diadakan oleh Dinas Lingkungan Hidup.','Jumlah bibit yang ditanam seluruhnya 1.000 bibit.','Kegiatan dilaksanakan di Pantai Kuta.'],ans:[0,1],
logika:`Ada informasi yang tertulis langsung, ada juga yang perlu dihitung dari data di teks.`,
langkah:`Penyelenggara: Dinas Lingkungan Hidup ✅<br>500 pelajar × 2 bibit = 1.000 bibit ✅<br>Tempatnya Pantai Kenjeran, bukan Kuta ❌`,
cepat:`Cek nama tempat, tanggal, dan angka dengan teliti. Pengecoh sering mengganti satu kata saja.`,
simpel:`Penyelenggaranya Dinas Lingkungan Hidup, dan bibitnya 500 × 2 = 1.000. Tempatnya Kenjeran, bukan Kuta.`},
{lv:2,sub:'deskripsi',t:'pg',q:`${TX('<p>Burung cendrawasih hidup di hutan Papua. Burung jantan memiliki bulu ekor yang panjang dan berwarna kuning keemasan. Saat musim kawin, burung jantan menari di dahan pohon sambil mengembangkan bulunya untuk menarik perhatian burung betina. Bulu burung betina berwarna cokelat dan tidak secantik bulu jantan.</p>')}<p>Mengapa burung cendrawasih jantan menari sambil mengembangkan bulunya?</p>`,
o:['untuk menarik perhatian burung betina','untuk mengusir burung lain dari hutan','karena bulunya basah terkena hujan','agar terlihat oleh manusia'],ans:0,
logika:`Cari kata "untuk" yang menunjukkan tujuan di kalimat tentang menari.`,
langkah:`"… menari di dahan pohon sambil mengembangkan bulunya untuk menarik perhatian burung betina."`,
cepat:`Pertanyaan "mengapa" bisa dijawab dengan tujuan (untuk/agar) atau sebab (karena).`,
simpel:`Burung jantan menari supaya burung betina tertarik padanya.`},
{lv:3,sub:'prosedur',t:'bs',q:`${TX('<p><b>Cara Membuat Tempat Pensil dari Botol Bekas</b><br>1. Cuci botol plastik bekas hingga bersih, lalu keringkan.<br>2. Potong botol bagian bawah setinggi 12 cm. Mintalah bantuan orang dewasa saat memotong.<br>3. Haluskan bagian tepi potongan dengan amplas agar tidak melukai tangan.<br>4. Bungkus botol dengan kertas kado, lalu rekatkan dengan lem.<br>5. Hias dengan stiker atau gambar sesuai selera.</p>')}<p>Tentukan benar atau salah pernyataan berikut!</p>`,
o:['Botol dibungkus kertas kado sebelum tepinya dihaluskan.','Amplas dipakai agar tepi potongan tidak melukai tangan.','Anak-anak disarankan meminta bantuan orang dewasa saat memotong botol.'],ans:[false,true,true],
logika:`Untuk pernyataan urutan, bandingkan nomor langkahnya.`,
langkah:`Menghaluskan = langkah 3, membungkus = langkah 4. Jadi membungkus dilakukan <b>sesudah</b> menghaluskan ❌<br>Tujuan amplas tertulis di langkah 3 ✅ · Saran meminta bantuan tertulis di langkah 2 ✅`,
cepat:`Kata "sebelum" dan "sesudah" pada soal → langsung bandingkan nomor langkahnya.`,
simpel:`Tepinya dihaluskan dulu, baru dibungkus kertas kado. Jadi pernyataan 1 salah.`},
{lv:3,sub:'laporan',t:'pg',q:`${TX('<p>Kelas 6A mendata kegiatan siswa setelah pulang sekolah. Dari 32 siswa, 12 siswa mengikuti les, 10 siswa membantu orang tua, 6 siswa bermain di luar rumah, dan sisanya bermain gawai.</p>')}<p>Pernyataan yang sesuai dengan data tersebut adalah …</p>`,
o:['Siswa yang bermain gawai ada 4 orang.','Siswa yang membantu orang tua paling banyak.','Siswa yang bermain di luar rumah lebih banyak daripada yang mengikuti les.','Seluruh siswa kelas 6A ada 28 orang.'],ans:0,
logika:`Informasi "sisanya" tidak ditulis angkanya. Hitung dari data yang ada.`,
langkah:`Gawai = 32 − 12 − 10 − 6 = 4 ✅<br>Paling banyak adalah les (12) · Bermain di luar (6) < les (12) · Jumlah siswa 32, bukan 28.`,
cepat:`Kalau ada kata "sisanya", total dikurangi semua angka yang disebut.`,
simpel:`32 dikurangi 12, 10, dan 6 hasilnya 4. Jadi yang bermain gawai 4 siswa.`},
{lv:3,sub:'berita',t:'pg',q:`${TX('<p>BOGOR – Hujan deras yang mengguyur sejak sore menyebabkan pohon tumbang di Jalan Pajajaran, Selasa (14/1) malam. Pohon setinggi 15 meter itu menutup dua lajur jalan sehingga lalu lintas macet sekitar dua jam. Petugas pemadam kebakaran memotong batang pohon dan jalan dapat dilalui kembali pukul 22.00.</p>')}<p>Unsur <b>bagaimana</b> (how) dalam berita tersebut adalah …</p>`,
o:['Petugas pemadam kebakaran memotong batang pohon sehingga jalan dapat dilalui kembali.','Hujan deras mengguyur sejak sore.','Peristiwa terjadi pada Selasa malam.','Peristiwa terjadi di Jalan Pajajaran, Bogor.'],ans:0,
logika:`Unsur "bagaimana" menjelaskan jalannya peristiwa atau cara mengatasinya. "Mengapa" = sebab, "kapan" = waktu, "di mana" = tempat.`,
langkah:`Hujan deras = sebab (mengapa). Selasa malam = kapan. Jalan Pajajaran = di mana. Cara petugas menangani pohon = <b>bagaimana</b>.`,
cepat:`Kelompokkan setiap kalimat ke 5W+1H. Pilihan yang tersisa adalah jawaban "bagaimana".`,
simpel:`"Bagaimana" artinya cara kejadian itu ditangani: petugas memotong pohon.`}
]},
/* ============ 4. TERSIRAT ============ */
{id:'tersirat',el:'info',ic:'🧠',nama:'Informasi Tersirat & Menyimpulkan',
subs:[['tersirat','Informasi Tersirat'],['sebab','Sebab-Akibat'],['fakta','Fakta & Opini']],
konsep:`<ul><li><b>Informasi tersirat</b> tidak ditulis langsung, tetapi bisa <b>disimpulkan</b> dari petunjuk di teks.</li><li>Simpulan yang baik harus <b>didukung bukti</b> di teks, tidak boleh mengarang.</li><li><b>Fakta</b> = kenyataan yang bisa dibuktikan (angka, waktu, tempat, kejadian).<br><b>Opini</b> = pendapat atau perasaan seseorang (cantik, sebaiknya, menurut saya, sangat bermanfaat).</li><li>Sebab-akibat: kata karena, sebab, akibatnya, sehingga, oleh karena itu.</li></ul>`,
soal:[
{lv:1,sub:'tersirat',t:'pg',q:`${TX('<p>Rina melihat ke luar jendela. Langit gelap dan angin bertiup kencang. Ia segera mengangkat jemuran dan menutup semua jendela rumah.</p>')}<p>Hal yang dapat disimpulkan dari teks tersebut adalah …</p>`,
o:['Hujan akan segera turun.','Hari sudah malam.','Rina akan pergi bermain.','Jemuran Rina sudah kering.'],ans:0,
logika:`Teks tidak menyebut kata "hujan", tetapi petunjuknya ada: langit gelap, angin kencang, mengangkat jemuran.`,
langkah:`Langit gelap + angin kencang = tanda akan hujan. Tindakan Rina (mengangkat jemuran, menutup jendela) mendukung simpulan itu.`,
cepat:`Kumpulkan petunjuk, lalu tanya: "Apa yang paling masuk akal?"`,
simpel:`Langit gelap, angin kencang, dan jemuran diangkat. Pasti sebentar lagi hujan.`},
{lv:1,sub:'fakta',t:'pg',q:`<p>Kalimat berikut yang merupakan <b>opini</b> adalah …</p>`,
o:['Pantai Parangtritis adalah pantai paling indah di Indonesia.','Pantai Parangtritis terletak di Kabupaten Bantul.','Banyak wisatawan datang ke Pantai Parangtritis setiap libur.','Ombak di Pantai Parangtritis cukup tinggi.'],ans:0,
logika:`Opini memuat penilaian pribadi yang bisa berbeda-beda antarorang.`,
langkah:`"Paling indah" adalah penilaian. Orang lain bisa menganggap pantai lain lebih indah. Pilihan lain bisa dibuktikan (lokasi, kunjungan wisatawan, ombak).`,
cepat:`Cari kata penilaian: paling, indah, bagus, sebaiknya, menurut saya.`,
simpel:`"Paling indah" itu pendapat. Setiap orang bisa punya pendapat berbeda.`},
{lv:1,sub:'sebab',t:'pg',q:`${TX('<p>Tono lupa membawa payung. Akibatnya, bajunya basah kuyup saat pulang sekolah.</p>')}<p>Penyebab baju Tono basah kuyup adalah …</p>`,
o:['Tono lupa membawa payung saat hujan.','Tono bermain air di sekolah.','Tono terjatuh ke selokan.','Tono mencuci bajunya.'],ans:0,
logika:`Kata "akibatnya" menunjukkan kalimat sebelumnya adalah sebab.`,
langkah:`Sebab: lupa membawa payung → akibat: baju basah. Hujan tersirat karena payung dipakai saat hujan.`,
cepat:`Kalimat sebelum kata "akibatnya" adalah sebabnya.`,
simpel:`Tono tidak bawa payung, jadi kehujanan dan bajunya basah.`},
{lv:2,sub:'tersirat',t:'pg',q:`${TX('<p>Pak Darto membuka toko pukul enam pagi. Ia menyapu lantai, menata dagangan, dan mencatat barang yang habis. Saat pembeli datang, ia melayani dengan ramah. Malam harinya, ia menghitung uang dengan teliti sebelum menutup toko.</p>')}<p>Sifat Pak Darto yang tersirat dalam teks adalah …</p>`,
o:['rajin dan teliti','pemarah dan kikir','malas dan ceroboh','sombong dan pendiam'],ans:0,
logika:`Sifat tidak disebut langsung. Simpulkan dari tindakan tokoh.`,
langkah:`Buka toko pagi-pagi, menyapu, menata dagangan = <b>rajin</b>. Mencatat barang habis dan menghitung uang dengan teliti = <b>teliti</b>. Ramah juga, tetapi pilihan jawabannya hanya "rajin dan teliti".`,
cepat:`Ubah setiap tindakan menjadi sifat, lalu cocokkan dengan pilihan jawaban.`,
simpel:`Pak Darto bangun pagi untuk bekerja dan menghitung uang dengan teliti. Jadi ia rajin dan teliti.`},
{lv:2,sub:'fakta',t:'bs',label:['Fakta','Opini'],q:`${TX('<p>(1) Candi Borobudur dibangun pada abad ke-8.<br>(2) Menurut saya, Borobudur adalah tempat wisata yang paling menyenangkan.<br>(3) Candi Borobudur memiliki 72 stupa berlubang di bagian atasnya.</p>')}<p>Tentukan apakah setiap kalimat merupakan fakta atau opini!</p>`,
o:['Kalimat (1)','Kalimat (2)','Kalimat (3)'],ans:[true,false,true],
logika:`Fakta bisa dibuktikan dengan data atau catatan sejarah. Opini berasal dari perasaan atau pendapat.`,
langkah:`(1) Abad ke-8 → bisa dibuktikan sejarah → fakta.<br>(2) "Menurut saya … paling menyenangkan" → opini.<br>(3) 72 stupa → bisa dihitung → fakta.`,
cepat:`Ada frasa "menurut saya", "sebaiknya", atau kata "paling + sifat"? Hampir pasti opini.`,
simpel:`Kalimat 1 dan 3 bisa dibuktikan, jadi fakta. Kalimat 2 pendapat pribadi, jadi opini.`},
{lv:2,sub:'sebab',t:'pgk',q:`${TX('<p>Sejak taman kota dibangun di dekat sungai, warga tidak lagi membuang sampah ke sungai. Air sungai menjadi lebih bersih. Ikan-ikan kecil mulai terlihat lagi, dan anak-anak senang bermain di taman sambil mengamati ikan.</p>')}<p>Pernyataan sebab-akibat yang sesuai dengan teks adalah …</p>`,
o:['Warga berhenti membuang sampah ke sungai sehingga air sungai lebih bersih.','Air sungai yang bersih membuat ikan-ikan kecil terlihat lagi.','Ikan-ikan kecil menyebabkan taman kota dibangun.'],ans:[0,1],
logika:`Susun rantai sebab-akibatnya berurutan.`,
langkah:`Taman dibangun → warga tidak membuang sampah → air bersih → ikan muncul → anak-anak senang.<br>Pernyataan 1 dan 2 sesuai urutan ✅ · Pernyataan 3 membalik sebab-akibat ❌`,
cepat:`Gambar panah dari sebab ke akibat. Pernyataan yang arah panahnya terbalik pasti salah.`,
simpel:`Sampah berkurang → sungai bersih → ikan datang. Ikan bukan penyebab taman dibangun.`},
{lv:3,sub:'tersirat',t:'bs',label:['Sesuai','Tidak Sesuai'],q:`${TX('<p>Bu Sari memandangi papan pengumuman sambil tersenyum lebar. Nama Dimas, anaknya, tertulis di urutan pertama. Ia segera menelepon suaminya dengan suara bergetar. "Ayah, anak kita berhasil!" Matanya berkaca-kaca.</p>')}<p>Tentukan apakah simpulan berikut sesuai atau tidak sesuai dengan teks!</p>`,
o:['Dimas meraih hasil terbaik dalam suatu pengumuman.','Bu Sari merasa terharu dan bangga.','Bu Sari sedih karena Dimas gagal.'],ans:[true,true,false],
logika:`Tanda-tanda emosi (tersenyum lebar, mata berkaca-kaca, "berhasil") dapat dibaca untuk menyimpulkan perasaan.`,
langkah:`Nama di urutan pertama → hasil terbaik ✅<br>Tersenyum + suara bergetar + mata berkaca-kaca + "berhasil" → terharu dan bangga ✅<br>Mata berkaca-kaca di sini karena bahagia, bukan sedih ❌`,
cepat:`Mata berkaca-kaca bisa karena senang atau sedih. Lihat kata pendukungnya, misalnya "tersenyum" dan "berhasil".`,
simpel:`Dimas juara pertama, jadi ibunya menangis karena bahagia, bukan karena sedih.`},
{lv:3,sub:'fakta',t:'pg',q:`${TX('<p>Kantin sekolah kini menjual buah potong setiap hari. Harga satu porsi Rp3.000. Dalam seminggu terjual 200 porsi. Menurut Bu Kantin, buah potong adalah jajanan paling sehat untuk anak-anak. Sebaiknya semua kantin sekolah menjual buah.</p>')}<p>Kalimat fakta yang terdapat pada teks adalah …</p>`,
o:['Dalam seminggu terjual 200 porsi buah potong.','Buah potong adalah jajanan paling sehat untuk anak-anak.','Sebaiknya semua kantin sekolah menjual buah.','Buah potong pasti disukai semua anak.'],ans:0,
logika:`Fakta berisi data yang bisa diperiksa. Opini berisi penilaian atau saran.`,
langkah:`"200 porsi" adalah data penjualan → fakta. "Paling sehat" adalah penilaian, "sebaiknya" adalah saran, dan pilihan terakhir tidak ada di teks.`,
cepat:`Angka dan data penjualan = fakta. Kata "paling", "sebaiknya", dan "pasti" biasanya opini.`,
simpel:`Jumlah porsi yang terjual bisa dihitung, jadi itu fakta.`},
{lv:3,sub:'sebab',t:'pg',q:`${TX('<p>Musim kemarau tahun ini sangat panjang. Sawah-sawah mengering dan petani gagal panen. Persediaan beras di pasar berkurang, sedangkan pembeli tetap banyak.</p>')}<p>Akibat yang paling mungkin terjadi berdasarkan teks adalah …</p>`,
o:['Harga beras di pasar naik.','Harga beras di pasar turun.','Petani menanam padi dua kali lebih banyak.','Pembeli beras berkurang drastis.'],ans:0,
logika:`Teks tidak menyebut harga. Simpulkan dari keadaan: barang sedikit, pembeli tetap banyak.`,
langkah:`Kemarau → gagal panen → beras berkurang. Barang sedikit sedangkan peminat tetap banyak → harga cenderung <b>naik</b>.`,
cepat:`Pola umum: barang langka + pembeli tetap = harga naik.`,
simpel:`Berasnya sedikit tetapi pembelinya banyak, jadi harganya naik.`}
]},
/* ============ 5. UNSUR CERITA ============ */
{id:'cerita',el:'sastra',ic:'🦊',nama:'Unsur Cerita (Fabel, Dongeng, Cerpen)',
subs:[['tokoh','Tokoh & Watak'],['alur','Alur & Urutan Peristiwa'],['latar','Latar & Suasana'],['amanat','Amanat & Nilai']],
konsep:`<ul><li><b>Tokoh</b>: pelaku cerita. <b>Watak</b>: sifat tokoh, dilihat dari tindakan, ucapan, dan pendapat tokoh lain.</li><li><b>Alur</b>: urutan peristiwa (pengenalan → masalah → puncak → penyelesaian).</li><li><b>Latar</b>: tempat, waktu, dan suasana.</li><li><b>Amanat</b>: pesan atau nasihat dari cerita. Biasanya berkaitan dengan akibat dari perbuatan tokoh.</li><li>Fabel = cerita dengan tokoh hewan yang berperilaku seperti manusia.</li></ul>`,
soal:[
{lv:1,sub:'tokoh',t:'pg',q:`${TX('<p>Siput berjalan sangat pelan menuju pohon mangga. Belalang mengejeknya, "Kau tidak akan sampai sebelum malam!" Siput tidak marah. Ia terus berjalan dengan sabar dan akhirnya tiba di bawah pohon tepat saat matahari terbenam.</p>')}<p>Watak tokoh Siput adalah …</p>`,
o:['sabar dan pantang menyerah','sombong dan pemarah','malas dan penakut','licik dan curang'],ans:0,
logika:`Watak dilihat dari tindakan tokoh saat menghadapi masalah.`,
langkah:`Siput diejek tetapi "tidak marah" (sabar) dan "terus berjalan" sampai tiba (pantang menyerah).`,
cepat:`Cari kata kerja yang dilakukan tokoh, lalu ubah menjadi sifat.`,
simpel:`Siput tidak marah walau diejek dan terus berjalan. Siput sabar dan tidak menyerah.`},
{lv:1,sub:'latar',t:'pg',q:`${TX('<p>Malam itu bulan bersinar terang. Di tepi hutan, para kunang-kunang berkumpul di atas semak-semak. Mereka sedang bersiap mengadakan pesta cahaya.</p>')}<p>Latar waktu dalam cerita tersebut adalah …</p>`,
o:['malam hari','pagi hari','siang hari','sore hari'],ans:0,
logika:`Latar waktu menjawab pertanyaan "kapan".`,
langkah:`Kalimat pertama: "<b>Malam</b> itu bulan bersinar terang."`,
cepat:`Cari kata yang menunjukkan waktu: pagi, siang, malam, kemarin, saat liburan.`,
simpel:`Di teks tertulis "malam itu". Jadi latarnya malam hari.`},
{lv:1,sub:'amanat',t:'pg',q:`${TX('<p>Kelinci menemukan banyak wortel di kebun. Ia memakan semuanya sendiri tanpa membaginya kepada teman-temannya. Malam harinya, perut Kelinci sakit sekali. Ia menyesal karena terlalu rakus.</p>')}<p>Amanat cerita tersebut adalah …</p>`,
o:['Jangan bersikap rakus dan suka berbagilah kepada teman.','Wortel adalah makanan yang tidak sehat.','Kelinci sebaiknya tinggal di kebun.','Kita harus makan pada malam hari.'],ans:0,
logika:`Amanat diambil dari kesalahan tokoh dan akibat yang ia terima.`,
langkah:`Kesalahan: rakus dan tidak berbagi. Akibatnya perut sakit dan menyesal. Pesannya: jangan rakus, berbagilah.`,
cepat:`Rumus amanat: "Jangan [kesalahan tokoh]" atau "Lakukan [kebalikan kesalahan tokoh]".`,
simpel:`Kelinci sakit perut karena rakus. Pesannya: jangan rakus dan suka berbagi.`},
{lv:2,sub:'alur',t:'pg',q:`${TX('<p>(1) Akhirnya, Doni mengembalikan dompet itu kepada pemiliknya, seorang nenek.<br>(2) Sepulang sekolah, Doni menemukan sebuah dompet di trotoar.<br>(3) Nenek itu sangat berterima kasih dan memuji kejujuran Doni.<br>(4) Ia membuka dompet itu dan menemukan kartu identitas berisi alamat pemiliknya.</p>')}<p>Urutan peristiwa yang tepat adalah …</p>`,
o:['(2) – (4) – (1) – (3)','(1) – (2) – (3) – (4)','(2) – (1) – (4) – (3)','(4) – (2) – (1) – (3)'],ans:0,
logika:`Cari kalimat pembuka (pengenalan), lalu ikuti hubungan sebab-akibatnya.`,
langkah:`(2) menemukan dompet → (4) membuka dan menemukan alamat → (1) "Akhirnya" mengembalikan → (3) nenek berterima kasih.`,
cepat:`Kata "akhirnya" menunjukkan bagian akhir. Kata "ia" atau "itu" merujuk pada peristiwa sebelumnya.`,
simpel:`Doni menemukan dompet, membukanya, mengembalikannya, lalu nenek berterima kasih.`},
{lv:2,sub:'tokoh',t:'bs',q:`${TX('<p>Saat kerja kelompok, Mira langsung membagi tugas kepada setiap anggota. Ketika Joni kesulitan menggambar, Mira duduk di sebelahnya dan mengajarinya. Namun, Mira juga mudah kesal jika ada teman yang datang terlambat.</p>')}<p>Tentukan benar atau salah pernyataan tentang watak Mira!</p>`,
o:['Mira memiliki jiwa pemimpin.','Mira peduli kepada teman yang kesulitan.','Mira selalu sabar dalam segala keadaan.'],ans:[true,true,false],
logika:`Satu tokoh bisa punya beberapa watak, termasuk kelemahannya.`,
langkah:`Membagi tugas = jiwa pemimpin ✅ · Mengajari Joni = peduli ✅ · "Mudah kesal" jika teman terlambat → tidak selalu sabar ❌`,
cepat:`Kata "namun" sering menunjukkan sisi lain atau kelemahan tokoh.`,
simpel:`Mira pemimpin dan peduli, tetapi ia mudah kesal. Jadi ia tidak selalu sabar.`},
{lv:2,sub:'latar',t:'pg',q:`${TX('<p>Pasar malam itu penuh sesak. Lampu warna-warni berkelip, musik terdengar keras dari komidi putar, dan anak-anak tertawa riang sambil memegang gulali.</p>')}<p>Suasana yang tergambar dalam teks tersebut adalah …</p>`,
o:['ramai dan meriah','sepi dan sunyi','tegang dan menakutkan','sedih dan haru'],ans:0,
logika:`Suasana disimpulkan dari gambaran suara, cahaya, dan perasaan tokoh.`,
langkah:`Penuh sesak, lampu warna-warni, musik keras, anak tertawa riang → suasana ramai dan meriah.`,
cepat:`Kumpulkan kata sifat dan suara di teks, lalu tentukan suasana yang paling cocok.`,
simpel:`Banyak orang, lampu, musik, dan tawa. Suasananya ramai dan meriah.`},
{lv:3,sub:'amanat',t:'pgk',q:`${TX('<p>Gagak menemukan sepotong keju. Rubah yang lapar memujinya, "Suaramu pasti merdu sekali, Gagak. Maukah kau bernyanyi untukku?" Gagak merasa tersanjung dan membuka paruhnya untuk bernyanyi. Keju pun jatuh dan langsung disambar Rubah. "Lain kali jangan mudah percaya pada pujian," kata Rubah sambil berlari pergi.</p>')}<p>Pesan moral yang dapat diambil dari cerita tersebut adalah …</p>`,
o:['Jangan mudah terbuai oleh pujian.','Waspadalah terhadap orang yang memuji karena punya maksud tertentu.','Bernyanyi dapat membuat kita kehilangan teman.'],ans:[0,1],
logika:`Lihat sebab Gagak kehilangan keju: ia terbuai pujian Rubah yang punya maksud tersembunyi.`,
langkah:`Gagak tersanjung → membuka paruh → keju jatuh. Pesannya: jangan mudah terbuai pujian ✅ dan waspada pada pujian yang punya maksud tertentu ✅<br>Bernyanyi bukan masalahnya ❌`,
cepat:`Amanat bisa tersurat (diucapkan tokoh) atau tersirat. Di sini Rubah mengucapkannya langsung.`,
simpel:`Gagak kehilangan keju karena senang dipuji. Pesannya: hati-hati dengan pujian.`},
{lv:3,sub:'alur',t:'bs',q:`${TX('<p>Lina sangat ingin ikut lomba menyanyi, tetapi ia demam dua hari sebelum lomba. Ia sedih dan hampir menyerah. Ibu merawatnya dan memintanya beristirahat cukup. Pada hari lomba, suaranya sudah pulih meski belum sempurna. Lina tetap tampil dan meraih juara ketiga. Ia tersenyum bangga.</p>')}<p>Tentukan benar atau salah pernyataan tentang alur cerita!</p>`,
o:['Masalah dalam cerita adalah Lina sakit menjelang lomba.','Puncak cerita adalah saat Ibu merawat Lina.','Penyelesaian cerita adalah Lina tetap tampil dan meraih juara ketiga.'],ans:[true,false,true],
logika:`Alur: pengenalan → masalah → puncak (titik paling menegangkan) → penyelesaian.`,
langkah:`Masalah: Lina demam ✅<br>Puncaknya adalah saat Lina sedih dan hampir menyerah, sedangkan Ibu merawat Lina termasuk bagian menuju penyelesaian ❌<br>Penyelesaian: tampil dan juara ketiga ✅`,
cepat:`Puncak = saat tokoh paling tertekan atau bimbang. Penyelesaian = bagaimana masalah berakhir.`,
simpel:`Masalahnya Lina sakit. Akhir ceritanya Lina tetap tampil dan juara tiga.`},
{lv:3,sub:'tokoh',t:'pg',q:`${TX('<p>"Ah, biar saja sampahnya. Nanti juga ada petugas kebersihan," kata Bima sambil melempar bungkus jajan ke lantai kelas. Sinta memungut bungkus itu dan membuangnya ke tempat sampah. "Kalau semua berpikir seperti itu, kelas kita tidak akan pernah bersih, Bim," katanya pelan.</p>')}<p>Pernyataan yang tepat tentang kedua tokoh adalah …</p>`,
o:['Bima kurang bertanggung jawab, sedangkan Sinta peduli kebersihan dan menegur dengan sopan.','Bima rajin, sedangkan Sinta pemarah.','Keduanya sama-sama tidak peduli kebersihan.','Sinta sombong karena merasa paling bersih.'],ans:0,
logika:`Bandingkan ucapan dan tindakan kedua tokoh.`,
langkah:`Bima membuang sampah sembarangan dan menyerahkannya ke petugas → kurang bertanggung jawab. Sinta memungut sampah dan menegur "dengan pelan" → peduli dan sopan.`,
cepat:`Perhatikan cara tokoh berbicara. Kata "pelan" menunjukkan Sinta tidak marah atau sombong.`,
simpel:`Bima buang sampah sembarangan. Sinta memungutnya dan menegur dengan sopan.`}
]},
/* ============ 6. PUISI & PANTUN ============ */
{id:'puisi',el:'sastra',ic:'🎐',nama:'Puisi & Pantun',
subs:[['objek','Objek & Tema Puisi'],['makna','Makna Kata & Majas'],['pantun','Pantun']],
konsep:`<ul><li><b>Objek/tema puisi</b>: hal utama yang dibicarakan penyair. Lihat judul dan kata yang sering muncul.</li><li><b>Majas</b>: perumpamaan (bagai, seperti, laksana), personifikasi (benda bersifat seperti manusia: "angin berbisik"), metafora ("engkau pelita").</li><li><b>Pantun</b>: 4 baris per bait, rima a-b-a-b, baris 1–2 <b>sampiran</b>, baris 3–4 <b>isi</b>.</li><li>Jenis pantun: nasihat, jenaka, teka-teki, agama, kasih sayang.</li></ul>`,
soal:[
{lv:1,sub:'objek',t:'pg',q:`${TX('<p class="puisi">Kau terbang tinggi di langit biru\nekor panjangmu menari-nari\nbenang tipis menahan langkahmu\nagar tak hilang dibawa pergi</p><p style="text-align:center;font-size:12px">(karya: Tim Latihan TKA)</p>')}<p>Objek yang digambarkan dalam puisi tersebut adalah …</p>`,
o:['layang-layang','burung elang','pesawat terbang','awan putih'],ans:0,
logika:`Kumpulkan ciri-ciri yang disebut: terbang di langit, berekor panjang, dan ditahan benang tipis.`,
langkah:`Benda yang terbang, berekor, dan ditahan benang adalah layang-layang. Burung dan pesawat tidak memakai benang.`,
cepat:`Cari ciri yang paling khas. Di sini "benang tipis".`,
simpel:`Terbang tinggi dan diikat benang, itu layang-layang.`},
{lv:1,sub:'pantun',t:'pg',q:`${TX('<p class="puisi">Buah salak buah kedondong\ndibeli Ibu di pasar pagi\njangan malas wahai adik sayang\nrajin belajar supaya pandai</p><p style="text-align:center;font-size:12px">(karya: Tim Latihan TKA)</p>')}<p>Baris yang merupakan <b>isi</b> pantun tersebut adalah …</p>`,
o:['baris ketiga dan keempat','baris pertama dan kedua','baris pertama dan ketiga','baris kedua dan keempat'],ans:0,
logika:`Dalam pantun, sampiran ada di baris 1–2 dan isi (maksud) ada di baris 3–4.`,
langkah:`Baris 1–2 tentang salak dan kedondong (sampiran). Baris 3–4 berisi nasihat rajin belajar (isi).`,
cepat:`Ingat: 2 baris atas = sampiran, 2 baris bawah = isi.`,
simpel:`Pesan pantun ada di dua baris terakhir.`},
{lv:1,sub:'makna',t:'pg',q:`${TX('<p class="puisi">Angin <b>berbisik</b> di sela daun\nmenyampaikan kabar hujan akan turun</p>')}<p>Kata <b>berbisik</b> pada larik tersebut menggambarkan …</p>`,
o:['bunyi angin yang pelan dan lembut','angin yang dapat berbicara seperti manusia','suara orang yang sedang berbisik','angin topan yang sangat kencang'],ans:0,
logika:`Angin tidak bisa berbisik. Penyair memakai majas personifikasi untuk menggambarkan bunyi angin.`,
langkah:`Berbisik = suara pelan. Jadi angin bertiup pelan dan lembut sehingga bunyinya seperti bisikan.`,
cepat:`Benda yang "berbuat seperti manusia" adalah personifikasi. Cari makna kiasannya, bukan arti harfiahnya.`,
simpel:`Angin bertiup pelan, bunyinya seperti orang berbisik.`},
{lv:2,sub:'makna',t:'pg',q:`${TX('<p class="puisi">Ibu, kasihmu <b>bagai sang surya</b>\nmenyinari dunia tanpa meminta kembali</p>')}<p>Makna larik tersebut adalah …</p>`,
o:['Kasih ibu diberikan dengan tulus tanpa mengharap balasan.','Ibu suka berjemur di bawah sinar matahari.','Kasih ibu hanya terasa pada siang hari.','Ibu meminta dibelikan lampu yang terang.'],ans:0,
logika:`"Bagai" adalah tanda majas perumpamaan. Kasih ibu dibandingkan dengan matahari.`,
langkah:`Matahari menyinari semua makhluk tanpa meminta balasan. Begitu pula kasih ibu: tulus dan tidak mengharap balasan.`,
cepat:`Untuk perumpamaan, tanya: "Apa sifat benda pembandingnya?" Sifat itulah yang dimaksud.`,
simpel:`Matahari memberi cahaya tanpa minta balasan. Kasih ibu juga begitu.`},
{lv:2,sub:'objek',t:'pgk',q:`${TX('<p class="puisi">Merah putih berkibar di tiang tinggi\ndi bawahnya kami berdiri tegak\nmengenang pahlawan yang telah pergi\nmenjaga negeri dengan semangat tak retak</p><p style="text-align:center;font-size:12px">(karya: Tim Latihan TKA)</p>')}<p>Pernyataan yang sesuai dengan isi puisi adalah …</p>`,
o:['Puisi menggambarkan suasana upacara bendera.','Penyair mengajak menghargai jasa pahlawan.','Puisi menceritakan pertandingan olahraga.'],ans:[0,1],
logika:`Perhatikan petunjuk: merah putih berkibar, berdiri tegak, mengenang pahlawan.`,
langkah:`Bendera berkibar + berdiri tegak = upacara ✅ · "Mengenang pahlawan" dan "menjaga negeri" = menghargai jasa pahlawan ✅<br>Tidak ada pertandingan olahraga ❌`,
cepat:`Pilihan yang tidak punya satu pun kata pendukung di puisi bisa langsung dicoret.`,
simpel:`Ada bendera, berdiri tegak, dan mengenang pahlawan. Itu upacara bendera.`},
{lv:2,sub:'pantun',t:'bs',q:`${TX('<p class="puisi">Ke pasar membeli tomat\ntomat dibawa pulang ke rumah\nkalau kamu ingin selamat\njangan lupa berdoa dan ibadah</p><p style="text-align:center;font-size:12px">(karya: Tim Latihan TKA)</p>')}<p>Tentukan benar atau salah pernyataan tentang pantun tersebut!</p>`,
o:['Pantun tersebut memiliki rima a-b-a-b.','Pantun tersebut termasuk pantun nasihat atau agama.','Baris pertama dan kedua merupakan isi pantun.'],ans:[true,true,false],
logika:`Rima dilihat dari bunyi akhir setiap baris.`,
langkah:`Akhir baris: tomat (a), rumah (b), selamat (a), ibadah (b) → a-b-a-b ✅<br>Isinya ajakan berdoa dan ibadah → nasihat/agama ✅<br>Baris 1–2 adalah sampiran ❌`,
cepat:`Garis bawahi suku kata terakhir tiap baris, lalu beri huruf a/b.`,
simpel:`Bunyi akhirnya -at, -ah, -at, -ah, jadi a-b-a-b. Isinya ada di baris 3–4.`},
{lv:3,sub:'makna',t:'pgk',q:`${TX('<p class="puisi">Sekolahku taman ilmu\ntempat benih cita-cita disemai\nguru tekun menyiram setiap waktu\nhingga tunas harapan tumbuh bersemi</p><p style="text-align:center;font-size:12px">(karya: Tim Latihan TKA)</p>')}<p>Pernyataan yang tepat tentang makna kiasan dalam puisi adalah …</p>`,
o:['"Taman ilmu" menggambarkan sekolah sebagai tempat menumbuhkan pengetahuan.','"Guru tekun menyiram" bermakna guru sabar mendidik murid.','"Benih cita-cita disemai" bermakna sekolah mempunyai kebun sayur.'],ans:[0,1],
logika:`Seluruh puisi memakai perbandingan dengan taman: benih, menyiram, tunas. Semua itu adalah kiasan untuk proses belajar.`,
langkah:`Taman ilmu = tempat pengetahuan tumbuh ✅ · Menyiram = mendidik dengan tekun ✅<br>Benih cita-cita = cita-cita yang mulai ditanamkan, bukan kebun sungguhan ❌`,
cepat:`Kalau semua kata dalam puisi berasal dari satu tema (taman), kemungkinan besar penyair memakai metafora.`,
simpel:`Sekolah diibaratkan taman, murid seperti benih, dan guru seperti tukang kebun yang merawatnya.`},
{lv:3,sub:'objek',t:'pg',q:`${TX('<p class="puisi">Dulu sungai ini jernih bernyanyi\nikan menari di antara batu\nkini airnya hitam dan sepi\nhanya plastik hanyut membisu</p><p style="text-align:center;font-size:12px">(karya: Tim Latihan TKA)</p>')}<p>Perasaan penyair dan tema puisi tersebut adalah …</p>`,
o:['sedih karena sungai tercemar','gembira karena sungai jernih','marah karena tidak ada ikan untuk dipancing','kagum pada keindahan batu sungai'],ans:0,
logika:`Bandingkan keadaan dulu dan kini. Perubahan dari baik menjadi buruk memunculkan perasaan sedih atau prihatin.`,
langkah:`Dulu: jernih, ikan menari. Kini: hitam, sepi, penuh plastik. Penyair prihatin dan sedih melihat sungai yang tercemar.`,
cepat:`Pola "dulu … kini …" → temukan perubahannya. Perubahan ke arah buruk berarti suasana sedih atau prihatin.`,
simpel:`Sungainya dulu bersih, sekarang kotor penuh plastik. Penyairnya sedih.`},
{lv:3,sub:'pantun',t:'pg',q:`<p>Lengkapi pantun berikut agar rimanya tepat!</p>${TX('<p class="puisi">Pergi ke hutan mencari rotan\nrotan diikat dengan tali\n…\nsupaya hidup tidak merugi</p>')}<p>Baris yang tepat untuk melengkapi pantun adalah …</p>`,
o:['jagalah alam tanam pepohonan','jangan buang sampah sembarangan di kelas','rajinlah menabung setiap hari','kalau ke pasar membeli roti'],ans:0,
logika:`Baris ke-3 harus berima dengan baris ke-1 (-an) dan menjadi bagian isi yang nyambung dengan baris ke-4.`,
langkah:`Baris 1 berakhiran "-tan" (rotan). "Pepohonan" berakhiran -an ✅ dan isinya nyambung dengan "supaya hidup tidak merugi".<br>"Hari" dan "roti" tidak berima dengan -an. "Di kelas" juga tidak berima.`,
cepat:`Cek rima dulu (bunyi akhir harus sama dengan baris 1), baru cek kesesuaian makna.`,
simpel:`Baris 1 berakhiran "-an", jadi baris 3 juga harus berakhiran "-an": pepohonan.`}
]},
/* ============ 7. MENILAI & RELEVANSI ============ */
{id:'evaluasi',el:'sastra',ic:'⚖️',nama:'Menilai Isi & Relevansi dengan Kehidupan',
subs:[['relevansi','Relevansi dengan Kehidupan'],['menilai','Menilai Sikap & Tindakan'],['perubahan','Perubahan Tokoh & Suasana']],
konsep:`<ul><li><b>Relevansi</b>: mencari peristiwa sehari-hari yang <b>mirip</b> dengan isi teks (masalah dan sikap tokohnya sama).</li><li><b>Menilai sikap</b>: tentukan apakah tindakan tokoh patut ditiru, lalu berikan alasan dari teks.</li><li><b>Perubahan watak</b>: bandingkan sikap tokoh di awal dan akhir cerita, lalu cari peristiwa penyebabnya.</li><li><b>Perubahan suasana</b>: dari senang menjadi tegang, dari takut menjadi lega, dan seterusnya.</li></ul>`,
soal:[
{lv:1,sub:'menilai',t:'pg',q:`${TX('<p>Saat ulangan, Beni melihat temannya menyontek. Beni tidak ikut menyontek. Ia tetap mengerjakan soal sendiri meskipun beberapa soal sulit.</p>')}<p>Sikap Beni yang patut dicontoh adalah …</p>`,
o:['jujur','pemalas','penakut','sombong'],ans:0,
logika:`Nilai sikap dari tindakannya: menolak menyontek dan mengerjakan sendiri.`,
langkah:`Tidak menyontek dan mengerjakan sendiri adalah wujud sikap <b>jujur</b>.`,
cepat:`Ubah tindakan positif tokoh menjadi satu kata sifat.`,
simpel:`Beni tidak menyontek. Itu sikap jujur.`},
{lv:1,sub:'relevansi',t:'pg',q:`${TX('<p>Warga Desa Sukamaju bergotong royong memperbaiki jembatan yang rusak akibat banjir. Ada yang membawa kayu, ada yang memasak untuk para pekerja.</p>')}<p>Peristiwa sehari-hari yang sesuai dengan isi teks adalah …</p>`,
o:['Siswa satu kelas bekerja sama membersihkan kelas sebelum lomba.','Seorang anak bermain gim sendirian di rumah.','Pedagang bersaing menjual barang paling murah.','Seorang siswa belajar sendiri di perpustakaan.'],ans:0,
logika:`Inti teks: bekerja sama (gotong royong). Cari peristiwa yang juga menunjukkan kerja sama.`,
langkah:`Membersihkan kelas bersama = kerja sama, sama seperti gotong royong. Pilihan lain dilakukan sendiri atau bersaing.`,
cepat:`Tentukan satu kata kunci nilai dari teks (kerja sama), lalu cari pilihan yang memiliki nilai yang sama.`,
simpel:`Teksnya tentang kerja sama. Pilihan yang juga bekerja bersama adalah membersihkan kelas bersama-sama.`},
{lv:1,sub:'perubahan',t:'pg',q:`${TX('<p>Awalnya Tika takut naik panggung. Setelah sering berlatih dan diberi semangat oleh gurunya, Tika berani membacakan puisi di depan seluruh siswa.</p>')}<p>Perubahan sikap Tika adalah …</p>`,
o:['dari penakut menjadi pemberani','dari pemberani menjadi penakut','dari pemalas menjadi rajin','dari sombong menjadi rendah hati'],ans:0,
logika:`Bandingkan sikap awal dan sikap akhir tokoh.`,
langkah:`Awal: takut naik panggung. Akhir: berani membaca puisi. Jadi dari penakut menjadi pemberani.`,
cepat:`Cari kata "awalnya" dan "setelah" atau "sekarang".`,
simpel:`Dulu Tika takut, sekarang berani.`},
{lv:2,sub:'relevansi',t:'pgk',q:`${TX('<p>Kancil terjebak di dalam lubang. Ia tidak panik, tetapi berpikir mencari jalan keluar. Kancil lalu berteriak bahwa langit akan runtuh. Hewan-hewan yang ketakutan melompat ke dalam lubang. Kancil pun memanjat punggung mereka dan keluar dari lubang.</p>')}<p>Pernyataan tentang sikap Kancil yang tepat adalah …</p>`,
o:['Sikap tenang saat menghadapi masalah patut dicontoh.','Cara Kancil membohongi hewan lain tidak patut ditiru.','Kancil adalah tokoh jujur yang patut ditiru seluruhnya.'],ans:[0,1],
logika:`Seorang tokoh bisa memiliki sikap baik dan sikap buruk sekaligus. Nilai keduanya secara terpisah.`,
langkah:`Tenang dan berpikir mencari jalan keluar → baik ✅<br>Berbohong bahwa langit runtuh → tidak patut ditiru ✅<br>Kancil berbohong, jadi ia bukan tokoh jujur ❌`,
cepat:`Hati-hati dengan kata "seluruhnya" atau "selalu". Tokoh jarang sempurna.`,
simpel:`Sikap tenangnya bagus, tetapi berbohongnya tidak boleh ditiru.`},
{lv:2,sub:'perubahan',t:'bs',label:['Sesuai','Tidak Sesuai'],q:`${TX('<p>Rombongan kami berjalan riang menyusuri jalan setapak sambil bernyanyi. Tiba-tiba kabut tebal turun dan jalan tidak terlihat. Kami berpegangan tangan dengan jantung berdebar. Setengah jam kemudian, kabut menipis dan kami melihat cahaya lampu pos penjaga. Kami bersorak lega.</p>')}<p>Tentukan apakah pernyataan tentang perubahan suasana berikut sesuai atau tidak sesuai!</p>`,
o:['Suasana awal cerita gembira.','Saat kabut turun, suasana berubah menjadi tegang.','Akhir cerita suasananya menakutkan.'],ans:[true,true,false],
logika:`Bagi cerita menjadi bagian awal, tengah, dan akhir, lalu tentukan suasana tiap bagian.`,
langkah:`Awal: riang, bernyanyi → gembira ✅ · Tengah: kabut, jantung berdebar → tegang ✅ · Akhir: bersorak lega → lega/senang, bukan menakutkan ❌`,
cepat:`Cari kata perasaan di setiap bagian: riang → berdebar → lega.`,
simpel:`Awalnya senang, lalu tegang karena kabut, akhirnya lega.`},
{lv:2,sub:'menilai',t:'pg',q:`${TX('<p>Ketika melihat seorang nenek kesulitan menyeberang jalan, Arif segera menghampiri dan menuntunnya menyeberang. Padahal, saat itu Arif sedang terburu-buru pergi ke tempat les.</p>')}<p>Penilaian yang paling tepat terhadap tindakan Arif adalah …</p>`,
o:['Tindakan Arif terpuji karena ia mau menolong meskipun sedang terburu-buru.','Tindakan Arif salah karena bisa terlambat les.','Tindakan Arif biasa saja karena nenek bisa menyeberang sendiri.','Tindakan Arif tidak perlu karena ada polisi.'],ans:0,
logika:`Penilaian harus disertai alasan dari teks.`,
langkah:`Arif menolong walaupun sedang terburu-buru. Ia mendahulukan orang yang membutuhkan → terpuji dan peduli.`,
cepat:`Pilih penilaian positif atau negatif yang alasannya ada di teks. Pilihan dengan alasan karangan (misalnya "ada polisi") pasti salah.`,
simpel:`Arif tetap menolong nenek walau sedang buru-buru. Itu sikap terpuji.`},
{lv:3,sub:'relevansi',t:'bs',label:['Relevan','Tidak Relevan'],q:`${TX('<p>Nina sering lupa mengerjakan PR karena terlalu lama menonton televisi. Ia kemudian membuat jadwal harian yang ditempel di dinding kamar: belajar pukul 16.00–17.30 dan menonton televisi hanya setelah PR selesai. Sejak itu, PR Nina selalu selesai tepat waktu.</p>')}<p>Tentukan apakah peristiwa berikut relevan atau tidak relevan dengan isi teks!</p>`,
o:['Seorang siswa membatasi waktu bermain gim agar sempat membaca buku.','Seorang anak membuat daftar tugas supaya tidak ada yang terlupa.','Seorang siswa menonton televisi semalaman sebelum ujian.'],ans:[true,true,false],
logika:`Inti teks: mengatur waktu dengan jadwal agar kewajiban selesai. Peristiwa yang relevan harus memiliki inti yang sama.`,
langkah:`Membatasi gim untuk membaca = mengatur waktu ✅<br>Membuat daftar tugas = membuat rencana ✅<br>Menonton semalaman = kebalikan dari sikap Nina setelah berubah ❌`,
cepat:`Peristiwa yang relevan harus memiliki masalah DAN solusi yang mirip dengan teks.`,
simpel:`Nina belajar mengatur waktu. Membatasi gim dan membuat daftar tugas juga mengatur waktu. Menonton semalaman tidak.`},
{lv:3,sub:'perubahan',t:'pgk',q:`${TX('<p>Raja Hutan, Singa, dulu suka memerintah hewan lain dengan kasar. Suatu hari ia terjerat jaring pemburu. Tidak ada hewan besar yang mau menolongnya. Hanya Tikus kecil yang datang dan menggigit jaring sampai putus. Sejak saat itu, Singa berbicara dengan lembut dan selalu menghargai hewan lain, sekecil apa pun.</p>')}<p>Pernyataan yang tepat tentang perubahan watak Singa adalah …</p>`,
o:['Singa berubah dari kasar menjadi rendah hati.','Peristiwa ditolong Tikus menjadi penyebab perubahan watak Singa.','Singa berubah karena dipaksa oleh pemburu.'],ans:[0,1],
logika:`Cari watak awal, watak akhir, dan peristiwa di antaranya yang menjadi penyebab.`,
langkah:`Awal: kasar · Akhir: lembut, menghargai → rendah hati ✅<br>Penyebab: ditolong Tikus kecil saat tidak ada yang mau menolong ✅<br>Pemburu tidak memaksanya berubah ❌`,
cepat:`Penyebab perubahan watak biasanya peristiwa yang membuat tokoh sadar atau menyesal.`,
simpel:`Singa jadi baik hati setelah ditolong Tikus kecil.`},
{lv:3,sub:'menilai',t:'pg',q:`${TX('<p>Kelas 6B akan memilih ketua kelas. Dodi berjanji membelikan jajan bagi teman yang memilihnya. Lia berjanji membuat jadwal piket yang adil dan mendengarkan usul semua teman. Ana tidak mau berbicara apa pun karena merasa pasti menang.</p>')}<p>Calon ketua kelas yang paling layak dipilih beserta alasannya adalah …</p>`,
o:['Lia, karena programnya bermanfaat bagi seluruh kelas.','Dodi, karena memberi jajan gratis.','Ana, karena paling percaya diri.','Dodi, karena paling banyak teman.'],ans:0,
logika:`Nilai setiap calon dari cara ia ingin memimpin, bukan dari hadiah atau rasa percaya diri yang berlebihan.`,
langkah:`Dodi memakai hadiah (tidak adil). Ana sombong dan tidak punya rencana. Lia punya program untuk semua dan mau mendengarkan teman → paling layak.`,
cepat:`Pilihan "terbaik" adalah yang bermanfaat untuk semua orang dan alasannya ada di teks.`,
simpel:`Lia punya rencana yang adil untuk semua teman. Dia yang paling pantas.`}
]}
];
